import java.util.*;
import java.io.*;

public class Main {
    static final long MOD = 1000000007;

    static long powerMod(long base, long exp, long mod) {
        long res = 1;
        long cur = base % mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = (res * cur) % mod;
            }
            cur = (cur * cur) % mod;
            exp >>= 1;
        }
        return res;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        long n = Long.parseLong(st.nextToken());
        long m = Long.parseLong(st.nextToken());

        if (m == 0) {
            System.out.println(powerMod(n, n - 1, MOD));
        } else if (m == 1) {
            System.out.println(powerMod(n, n, MOD));
        } else {
            long[] parent = new long[(int) n + 1];
            for (int i = 0; i <= n; i++) {
                parent[i] = i;
            }

            // find set with path compression
            class UnionFind {
                long find(long x) {
                    while (parent[(int) x] != x) {
                        parent[(int) x] = parent[(int) parent[(int) x]];
                        x = parent[(int) x];
                    }
                    return x;
                }

                void union(long a, long b) {
                    long pa = find(a);
                    long pb = find(b);
                    if (pa != pb) {
                        parent[(int) pb] = pa;
                    }
                }
            }

            UnionFind uf = new UnionFind();

            for (long i = 1; i < n; i++) {
                long b = (i * m) % n;
                uf.union(i, b);
            }

            Set<Long> uniqueParents = new HashSet<>();
            for (long i = 1; i < n; i++) {
                uniqueParents.add(uf.find(i));
            }
            long count = uniqueParents.size();
            System.out.println(powerMod(n, count, MOD));
        }
    }
}
